def solve(rows):
    kept = []
    state = 4
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0  # Handle cases where the string inside pipes isn't an integer
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        keep_row = (state + weight + i) % 7 != 5 or i == len(rows) - 1
        if keep_row:
            kept.append(row)

        if weight == 0:
            state = 4
        else:
            state = (5 * state + weight) % 7

    if not kept:
        return []

    final_state = state
    kept_length = len(kept)
    rotation_amount = final_state % kept_length
    rotated_kept = kept[rotation_amount:] + kept[:rotation_amount]

    # Main rule: Rows [group, score, timestamp, name]
    result = {}
    for row in rotated_kept:
        if len(row) == 4 and isinstance(row, list):
            group, score, timestamp, name = row
            if group not in result:
                result[group] = (score, timestamp, name)
            else:
